import { createRouter, createWebHashHistory, type RouteRecordRaw } from 'vue-router'
import { pinia } from '../pinia'
import { useAuthStore } from '../../stores/auth'
import LoginPage from '../../pages/LoginPage.vue'
import DashboardPage from '../../pages/DashboardPage.vue'
import ComingSoonPage from '../../pages/ComingSoonPage.vue'
import AppShell from '../../layouts/AppShell.vue'
import type { UserRole } from '../../types/legacy'
const managers:UserRole[]=['teacher','admin']
const routes:RouteRecordRaw[]=[{path:'/login',component:LoginPage,meta:{public:true,title:'Đăng nhập'}},{path:'/',component:AppShell,children:[{path:'',redirect:'/dashboard'},{path:'dashboard',component:DashboardPage,meta:{title:'Tổng quan'}},{path:'register',component:ComingSoonPage,meta:{title:'Đăng ký tự học'}},{path:'review',component:ComingSoonPage,meta:{title:'Duyệt đăng ký',roles:managers}},{path:'tracking',component:ComingSoonPage,meta:{title:'Theo dõi cả lớp',roles:['monitor',...managers]}},{path:'weeks',component:ComingSoonPage,meta:{title:'Quản lý tuần',roles:managers}},{path:'schedule',component:ComingSoonPage,meta:{title:'Thời khóa biểu',roles:managers}},{path:'students',component:ComingSoonPage,meta:{title:'Học sinh',roles:managers}},{path:'statistics',component:ComingSoonPage,meta:{title:'Thống kê',roles:managers}},{path:'history',component:ComingSoonPage,meta:{title:'Lịch sử'}},{path:'comments',component:ComingSoonPage,meta:{title:'Nhận xét GV'}},{path:'admin',component:ComingSoonPage,meta:{title:'Quản trị',roles:['admin']}},{path:'settings',component:ComingSoonPage,meta:{title:'Cài đặt'}}]},{path:'/:pathMatch(.*)*',redirect:'/dashboard'}]
export const router=createRouter({history:createWebHashHistory(),routes})
router.beforeEach(async to=>{const auth=useAuthStore(pinia);if(!auth.ready)await auth.bootstrap();if(to.meta.public)return auth.isAuthenticated?'/dashboard':true;if(!auth.isAuthenticated)return{path:'/login',query:{redirect:to.fullPath}};const roles=to.meta.roles as UserRole[]|undefined;if(roles&&!roles.includes(auth.currentUser!.role))return'/dashboard';return true})
